const tf = require("@tensorflow/tfjs");
(async () => {
  await tf.setBackend("cpu"); await tf.ready();
  const init = tf.randomNormal([3, 3], 0, 0.05);
  const v = tf.variable(init);
  const before = Array.from(v.dataSync()).map(x => +x.toFixed(6));
  init.dispose();
  let alive = true, after;
  try { after = Array.from(v.dataSync()).map(x => +x.toFixed(6)); } catch (e) { alive = false; console.log("read after dispose threw:", e.message); }
  if (alive) console.log("still readable & equal:", JSON.stringify(before) === JSON.stringify(after));
  // can optimizer still train it?
  const loss = tf.tidy(() => v.square().sum());
  const opt = tf.train.sgd(0.1);
  opt.minimize(() => v.square().sum(), false, [v]);
  opt.dispose();
  const changed = Array.from(v.dataSync())[0] !== after[0];
  console.log("trainable after source dispose:", changed, "| tensors alive:", tf.memory().numTensors);
})().catch(e => { console.error("ERR", e); process.exit(1); });
